import React, { useState, useEffect } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { productsApi, categoriesApi, cartsApi, reviewsApi } from '../services/api';

const ShopDetail = () => {
    const navigate = useNavigate();

    // Lấy ID sản phẩm từ URL: /shop-detail/:id
    const { id } = useParams();

    // --- STATE LƯU DỮ LIỆU ---
    const [product, setProduct] = useState(null);
    const [categories, setCategories] = useState([]);
    const [featured, setFeatured] = useState([]);

    const [cartCount, setCartCount] = useState(0);
    const [heroSearch, setHeroSearch] = useState('');

    // State cho trang chi tiết
    const [quantity, setQuantity] = useState(1);
    const [activeTab, setActiveTab] = useState('description');

    // State cho đánh giá
    const [reviews, setReviews] = useState([]);

    // --- HÀM ĐỊNH DẠNG TIỀN VNĐ ---
    const formatCurrency = (value) => {
        return Number(value || 0).toLocaleString('vi-VN') + ' đ';
    };

    // --- HÀM ĐỔI QUALITY SANG TIẾNG VIỆT ---
    const getQualityText = (quality) => {
        switch (quality) {
            case 'Organic':
                return 'Hữu cơ';
            case 'Fresh':
                return 'Tươi mới';
            case 'Sales':
                return 'Bán chạy';
            case 'Discount':
                return 'Giảm giá';
            case 'Expired':
                return 'Hết hạn';
            case 'Premium':
                return 'Cao cấp';
            default:
                return quality || 'Hữu cơ';
        }
    };

    // --- GỌI API LẤY DỮ LIỆU ---
    useEffect(() => {
        // Lấy chi tiết sản phẩm
        if (id) {
            productsApi.getById(id)
                .then(res => setProduct(res.data))
                .catch(err => console.log('Lỗi tải sản phẩm chi tiết: ', err));

            // Lấy danh sách đánh giá của sản phẩm
            reviewsApi.getByProductId(id)
                .then(res => setReviews(res.data))
                .catch(err => console.log('Lỗi tải danh sách đánh giá: ', err));
        } else {
            // Trường hợp người dùng vào /shop-detail không có ID
            productsApi.getAll()
                .then(res => {
                    const items = res.data.items || res.data;
                    if (items.length > 0) {
                        setProduct(items[0]);

                        reviewsApi.getByProductId(items[0].id)
                            .then(revRes => setReviews(revRes.data))
                            .catch(err => console.log('Lỗi tải đánh giá sản phẩm mặc định: ', err));
                    }
                })
                .catch(err => console.log('Lỗi tải danh sách sản phẩm: ', err));
        }

        // Lấy danh mục
        categoriesApi.getAll()
            .then(res => setCategories(res.data))
            .catch(err => console.log('Lỗi tải danh mục: ', err));

        // Lấy sản phẩm nổi bật
        productsApi.getFeatured()
            .then(res => setFeatured(res.data))
            .catch(err => console.log('Lỗi tải sản phẩm nổi bật: ', err));

        // Lấy ID người dùng để đếm giỏ hàng
        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (currentUserId) {
            cartsApi.getByUserId(currentUserId)
                .then(res => setCartCount(res.data.length || 0))
                .catch(err => console.log('Lỗi đếm giỏ hàng: ', err));
        } else {
            setCartCount(0);
        }
    }, [id]);

    // --- XỬ LÝ SỐ LƯỢNG MUA ---
    const decreaseQuantity = () => {
        if (quantity > 1) {
            setQuantity(quantity - 1);
        }
    };

    const increaseQuantity = () => {
        if (product && quantity < product.stock) {
            setQuantity(quantity + 1);
        } else {
            alert(`Trong kho chỉ còn ${product?.stock} sản phẩm thôi ní ơi!`);
        }
    };

    // --- THÊM VÀO GIỎ HÀNG ---
    const handleAddToCart = async (e, itemToBuy, qty = 1) => {
        e.preventDefault();

        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            alert('Vui lòng đăng nhập để có thể mua hàng!');
            navigate('/login');
            return;
        }

        try {
            await cartsApi.addToCart({
                userId: currentUserId,
                productId: itemToBuy.id,
                quantity: qty
            });

            alert(`Đã thêm ${qty} "${itemToBuy.name}" vào giỏ hàng thành công! 🛒`);

            cartsApi.getByUserId(currentUserId)
                .then(res => setCartCount(res.data.length || 0))
                .catch(err => console.log('Lỗi cập nhật giỏ hàng: ', err));
        } catch (error) {
            console.error('Lỗi thêm vào giỏ hàng:', error);
            alert('Thêm vào giỏ hàng thất bại!');
        }
    };
    // --- TÌM KIẾM ---
    const handleHeroSearch = () => {
        const closeBtn = document.getElementById('close-search-modal');
        if (closeBtn) closeBtn.click();

        navigate('/shop', { state: { searchTerm: heroSearch } });
    };

    // --- HIỂN THỊ SAO ---
    const renderStars = (rating) => {
        const stars = [];

        for (let i = 1; i <= 5; i++) {
            stars.push(
                <i
                    key={i}
                    className={`fas fa-star ${i <= rating ? 'text-warning' : 'text-muted'}`}
                ></i>
            );
        }

        return stars;
    };
    const getAverageRating = () => {
        if (!reviews || reviews.length === 0) return 0;

        const total = reviews.reduce((sum, rev) => {
            return sum + Number(rev.rating || rev.Rating || 0);
        }, 0);

        return Number((total / reviews.length).toFixed(1));
    };

    const getReviewImageUrl = (imageUrl) => {
        if (!imageUrl) return '';

        if (imageUrl.startsWith('http')) {
            return imageUrl;
        }

        // Nếu backend chạy qua gateway 5000 thì giữ dòng này.
        // Nếu ảnh không hiện, đổi thành port APIService thật của ông.
        const backendUrl = 'http://localhost:5000';

        return `${backendUrl}${imageUrl}`;
    };
    if (!product) {
        return (
            <div className="text-center py-5 mt-5">
                <h2>Đang tải dữ liệu sản phẩm...</h2>
            </div>
        );
    }

    return (
        <>
            {/* Navbar start */}
            <div className="container-fluid fixed-top">
                <div className="container topbar bg-primary d-none d-lg-block">
                    <div className="d-flex justify-content-between">
                        <div className="top-info ps-2">
                            <small className="me-3">
                                <i className="fas fa-map-marker-alt me-2 text-secondary"></i>
                                <a href="#" className="text-white">236 Hoàng Quốc Việt, Hà Nội</a>
                            </small>

                            <small className="me-3">
                                <i className="fas fa-envelope me-2 text-secondary"></i>
                                <a href="#" className="text-white">Email@Example.com</a>
                            </small>
                        </div>

                        <div className="top-link pe-2">
                            <a href="#" className="text-white">
                                <small className="text-white mx-2">Chính sách bảo mật</small>/
                            </a>

                            <a href="#" className="text-white">
                                <small className="text-white mx-2">Điều khoản sử dụng</small>/
                            </a>

                            <a href="#" className="text-white">
                                <small className="text-white ms-2">Bán hàng & Hoàn tiền</small>
                            </a>
                        </div>
                    </div>
                </div>

                <div className="container px-0">
                    <nav className="navbar navbar-light bg-white navbar-expand-xl">
                        <Link to="/" className="navbar-brand">
                            <h1 className="text-primary display-6">Fruitables</h1>
                        </Link>

                        <button
                            className="navbar-toggler py-2 px-3"
                            type="button"
                            data-bs-toggle="collapse"
                            data-bs-target="#navbarCollapse"
                        >
                            <span className="fa fa-bars text-primary"></span>
                        </button>

                        <div className="collapse navbar-collapse bg-white" id="navbarCollapse">
                            <div className="navbar-nav mx-auto">
                                <Link to="/" className="nav-item nav-link">Trang chủ</Link>
                                <Link to="/shop" className="nav-item nav-link">Cửa hàng</Link>
                                <Link to="/shop-detail" className="nav-item nav-link active">Chi tiết sản phẩm</Link>

                                <div className="nav-item dropdown">
                                    <a href="#" className="nav-link dropdown-toggle" data-bs-toggle="dropdown">
                                        Trang
                                    </a>

                                    <div className="dropdown-menu m-0 bg-secondary rounded-0">
                                        <Link to="/cart" className="dropdown-item">Giỏ hàng</Link>
                                        <Link to="/checkout" className="dropdown-item">Thanh toán</Link>
                                    </div>
                                </div>

                                <Link to="/contact" className="nav-item nav-link">Liên hệ</Link>
                            </div>

                            <div className="d-flex m-3 me-0">
                                <button
                                    className="btn-search btn border border-secondary btn-md-square rounded-circle bg-white me-4"
                                    data-bs-toggle="modal"
                                    data-bs-target="#searchModal"
                                >
                                    <i className="fas fa-search text-primary"></i>
                                </button>

                                <Link to="/cart" className="position-relative me-4 my-auto">
                                    <i className="fa fa-shopping-bag fa-2x"></i>

                                    <span
                                        className="position-absolute bg-secondary rounded-circle d-flex align-items-center justify-content-center text-dark px-1"
                                        style={{
                                            top: '-5px',
                                            left: '15px',
                                            height: '20px',
                                            minWidth: '20px'
                                        }}
                                    >
                                        {cartCount}
                                    </span>
                                </Link>

                                {/* Menu đăng nhập */}
                                {(() => {
                                    const userStorage = localStorage.getItem('user');
                                    let currentUser = null;

                                    if (userStorage && userStorage !== 'undefined' && userStorage !== 'null') {
                                        try {
                                            currentUser = JSON.parse(userStorage);
                                        } catch (e) {
                                            console.error('Lỗi đọc thông tin người dùng', e);
                                        }
                                    }

                                    if (currentUser) {
                                        return (
                                            <div className="nav-item dropdown my-auto">
                                                <a
                                                    href="#"
                                                    className="nav-link dropdown-toggle d-flex align-items-center"
                                                    data-bs-toggle="dropdown"
                                                    style={{ padding: 0 }}
                                                >
                                                    <i className="fas fa-user fa-2x text-success"></i>
                                                    <span className="ms-2 fw-bold text-dark">
                                                        {currentUser.name || currentUser.userName}
                                                    </span>
                                                </a>

                                                <div className="dropdown-menu m-0 bg-secondary rounded-0">
                                                    {(currentUser.role === 'Admin' || currentUser.Role === 'Admin') && (
                                                        <Link to="/dashboard" className="dropdown-item fw-bold text-warning">
                                                            <i className="fas fa-cog me-2"></i>
                                                            Vào trang Quản trị
                                                        </Link>
                                                    )}

                                                    <Link to="/my-orders" className="dropdown-item">
                                                        Đơn hàng của tôi
                                                    </Link>

                                                    <a
                                                        href="#"
                                                        className="dropdown-item"
                                                        onClick={(e) => {
                                                            e.preventDefault();
                                                            localStorage.clear();
                                                            window.location.href = '/';
                                                        }}
                                                    >
                                                        <i className="fas fa-sign-out-alt me-2"></i>
                                                        Đăng xuất
                                                    </a>
                                                </div>
                                            </div>
                                        );
                                    }

                                    return (
                                        <Link to="/login" className="my-auto">
                                            <i className="fas fa-user fa-2x"></i>
                                        </Link>
                                    );
                                })()}
                            </div>
                        </div>
                    </nav>
                </div>
            </div>
            {/* Navbar End */}

            {/* Modal Search Start */}
            <div
                className="modal fade"
                id="searchModal"
                tabIndex="-1"
                aria-labelledby="exampleModalLabel"
                aria-hidden="true"
            >
                <div className="modal-dialog modal-fullscreen">
                    <div className="modal-content rounded-0">
                        <div className="modal-header">
                            <h5 className="modal-title" id="exampleModalLabel">
                                Tìm kiếm bằng từ khóa
                            </h5>

                            <button
                                type="button"
                                id="close-search-modal"
                                className="btn-close"
                                data-bs-dismiss="modal"
                                aria-label="Đóng"
                            ></button>
                        </div>

                        <div className="modal-body d-flex align-items-center">
                            <div className="input-group w-75 mx-auto d-flex">
                                <input
                                    type="search"
                                    className="form-control p-3"
                                    placeholder="Nhập từ khóa..."
                                    value={heroSearch}
                                    onChange={(e) => setHeroSearch(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleHeroSearch()}
                                />

                                <span
                                    id="search-icon-1"
                                    className="input-group-text p-3"
                                    style={{ cursor: 'pointer' }}
                                    onClick={handleHeroSearch}
                                >
                                    <i className="fa fa-search"></i>
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            {/* Modal Search End */}

            {/* Single Page Header start */}
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Chi tiết sản phẩm</h1>

                <ol className="breadcrumb justify-content-center mb-0">
                    <li className="breadcrumb-item">
                        <Link to="/">Trang chủ</Link>
                    </li>

                    <li className="breadcrumb-item">
                        <Link to="/shop">Cửa hàng</Link>
                    </li>

                    <li className="breadcrumb-item active text-white">
                        Chi tiết sản phẩm
                    </li>
                </ol>
            </div>
            {/* Single Page Header End */}

            {/* Single Product Start */}
            <div className="container-fluid mt-5 py-5">
                <div className="container py-5">
                    <div className="row g-4 mb-5">
                        <div className="col-lg-8 col-xl-9">
                            <div className="row g-4">
                                {/* Hình ảnh sản phẩm */}
                                <div className="col-lg-6">
                                    <div className="border rounded">
                                        <a href="#">
                                            <img
                                                src={product.imageUrl || '/img/single-item.jpg'}
                                                className="img-fluid rounded"
                                                alt={product.name}
                                                style={{
                                                    width: '100%',
                                                    objectFit: 'cover'
                                                }}
                                            />
                                        </a>
                                    </div>
                                </div>

                                {/* Thông tin sản phẩm */}
                                <div className="col-lg-6">
                                    <h4 className="fw-bold mb-3">{product.name}</h4>

                                    <p className="mb-3">
                                        Danh mục: {product.categoryName || product.category?.name || 'Sản phẩm'}
                                    </p>

                                    <h5 className="fw-bold mb-3">
                                        {(product.discountPrice || product.DiscountPrice) ? (
                                            <>
                                                <span className="text-danger">
                                                    {formatCurrency(product.discountPrice || product.DiscountPrice)}
                                                </span>

                                                <span className="text-muted text-decoration-line-through fs-6 ms-2">
                                                    {formatCurrency(product.price)}
                                                </span>
                                            </>
                                        ) : (
                                            formatCurrency(product.price)
                                        )}
                                    </h5>

                                    <div className="d-flex align-items-center mb-4">
                                        <div className="me-2">
                                            {renderStars(getAverageRating())}
                                        </div>

                                        <span className="text-muted">
                                            {reviews.length > 0
                                                ? `${getAverageRating()}/5 (${reviews.length} đánh giá)`
                                                : 'Chưa có đánh giá'}
                                        </span>
                                    </div>

                                    <p className="mb-4">
                                        {product.description || 'Sản phẩm này rất tươi ngon, đảm bảo chất lượng và phù hợp cho bữa ăn hằng ngày của gia đình bạn.'}
                                    </p>

                                    <p className="mb-4">
                                        Kho còn: <span className="fw-bold">{product.stock}</span> sản phẩm
                                    </p>

                                    {/* Bộ tăng giảm số lượng */}
                                    <div className="input-group quantity mb-5" style={{ width: '100px' }}>
                                        <div className="input-group-btn">
                                            <button
                                                className="btn btn-sm btn-minus rounded-circle bg-light border"
                                                onClick={decreaseQuantity}
                                            >
                                                <i className="fa fa-minus"></i>
                                            </button>
                                        </div>

                                        <input
                                            type="text"
                                            className="form-control form-control-sm text-center border-0"
                                            value={quantity}
                                            readOnly
                                        />

                                        <div className="input-group-btn">
                                            <button
                                                className="btn btn-sm btn-plus rounded-circle bg-light border"
                                                onClick={increaseQuantity}
                                            >
                                                <i className="fa fa-plus"></i>
                                            </button>
                                        </div>
                                    </div>

                                    {/* Nút thêm vào giỏ */}
                                    <button
                                        onClick={(e) => handleAddToCart(e, product, quantity)}
                                        className="btn border border-secondary rounded-pill px-4 py-2 mb-4 text-primary"
                                    >
                                        <i className="fa fa-shopping-bag me-2 text-primary"></i>
                                        Thêm vào giỏ hàng
                                    </button>
                                </div>

                                {/* Tab mô tả và đánh giá */}
                                <div className="col-lg-12">
                                    <nav>
                                        <div className="nav nav-tabs mb-3">
                                            <button
                                                className={`nav-link border-white border-bottom-0 ${activeTab === 'description' ? 'active' : ''}`}
                                                onClick={() => setActiveTab('description')}
                                            >
                                                Mô tả
                                            </button>

                                            <button
                                                className={`nav-link border-white border-bottom-0 ${activeTab === 'reviews' ? 'active' : ''}`}
                                                onClick={() => setActiveTab('reviews')}
                                            >
                                                Đánh giá
                                            </button>
                                        </div>
                                    </nav>

                                    <div className="tab-content mb-5">
                                        {/* Tab mô tả */}
                                        <div className={`tab-pane ${activeTab === 'description' ? 'active d-block' : 'd-none'}`}>
                                            <p>
                                                {product.description || 'Chưa có mô tả chi tiết cho sản phẩm này.'}
                                            </p>

                                            <div className="px-2 mt-4">
                                                <div className="row g-4">
                                                    <div className="col-6">
                                                        <div className="row bg-light align-items-center text-center justify-content-center py-2">
                                                            <div className="col-6">
                                                                <p className="mb-0">Khối lượng</p>
                                                            </div>

                                                            <div className="col-6">
                                                                <p className="mb-0">{product.weight || '1 kg'}</p>
                                                            </div>
                                                        </div>

                                                        <div className="row text-center align-items-center justify-content-center py-2">
                                                            <div className="col-6">
                                                                <p className="mb-0">Xuất xứ</p>
                                                            </div>

                                                            <div className="col-6">
                                                                <p className="mb-0">
                                                                    {product.countryOfOrigin || 'Nông trại Việt Nam'}
                                                                </p>
                                                            </div>
                                                        </div>

                                                        <div className="row bg-light text-center align-items-center justify-content-center py-2">
                                                            <div className="col-6">
                                                                <p className="mb-0">Chất lượng</p>
                                                            </div>

                                                            <div className="col-6">
                                                                <p className="mb-0">
                                                                    {getQualityText(product.quality || product.Quality)}
                                                                </p>
                                                            </div>
                                                        </div>

                                                        <div className="row text-center align-items-center justify-content-center py-2">
                                                            <div className="col-6">
                                                                <p className="mb-0">Tình trạng</p>
                                                            </div>

                                                            <div className="col-6">
                                                                <p className="mb-0">Đạt chuẩn</p>
                                                            </div>
                                                        </div>

                                                        <div className="row bg-light text-center align-items-center justify-content-center py-2">
                                                            <div className="col-6">
                                                                <p className="mb-0">Khối lượng tối thiểu</p>
                                                            </div>

                                                            <div className="col-6">
                                                                <p className="mb-0">250 g</p>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Tab đánh giá */}
                                        <div className={`tab-pane ${activeTab === 'reviews' ? 'active d-block' : 'd-none'}`}>
                                            {reviews && reviews.length > 0 ? (
                                                reviews.map((rev) => (
                                                    <div className="d-flex mb-4" key={rev.id}>
                                                        <img
                                                            src={rev.userImage || '/img/avatar.jpg'}
                                                            className="img-fluid rounded-circle p-3"
                                                            style={{
                                                                width: '100px',
                                                                height: '100px'
                                                            }}
                                                            alt="Ảnh người đánh giá"
                                                        />

                                                        <div className="flex-grow-1">
                                                            <p className="mb-2" style={{ fontSize: '14px' }}>
                                                                {new Date(rev.reviewDate).toLocaleDateString('vi-VN')}
                                                            </p>

                                                            <div className="d-flex justify-content-between">
                                                                <h5>{rev.userName || rev.name || 'Khách hàng'}</h5>

                                                                <div className="d-flex mb-3">
                                                                    {renderStars(rev.rating || rev.Rating)}
                                                                </div>
                                                            </div>

                                                            {(rev.imageUrl || rev.ImageUrl) && (
                                                                <div className="mt-3">
                                                                    <img
                                                                        src={getReviewImageUrl(rev.imageUrl || rev.ImageUrl)}
                                                                        alt="Ảnh đánh giá sản phẩm"
                                                                        className="img-fluid rounded border"
                                                                        style={{
                                                                            maxWidth: '180px',
                                                                            maxHeight: '180px',
                                                                            objectFit: 'cover'
                                                                        }}
                                                                    />
                                                                </div>
                                                            )}
                                                        </div>
                                                    </div>
                                                ))
                                            ) : (
                                                <p>
                                                    Chưa có đánh giá nào cho sản phẩm này. Hãy là người đầu tiên đánh giá sản phẩm nhé!
                                                </p>
                                            )}

                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Sidebar bên phải */}
                        <div className="col-lg-4 col-xl-3">
                            <div className="row g-4 fruite">
                                <div className="col-lg-12">
                                    {/* Tìm kiếm */}
                                    <div className="input-group w-100 mx-auto d-flex mb-4">
                                        <input
                                            type="search"
                                            className="form-control p-3"
                                            placeholder="Nhập từ khóa..."
                                            aria-describedby="search-icon-1"
                                            value={heroSearch}
                                            onChange={(e) => setHeroSearch(e.target.value)}
                                            onKeyDown={(e) => e.key === 'Enter' && handleHeroSearch()}
                                        />

                                        <span
                                            id="search-icon-1"
                                            className="input-group-text p-3"
                                            style={{ cursor: 'pointer' }}
                                            onClick={handleHeroSearch}
                                        >
                                            <i className="fa fa-search"></i>
                                        </span>
                                    </div>

                                    {/* Danh mục */}
                                    <div className="mb-4">
                                        <h4>Danh mục</h4>

                                        <ul className="list-unstyled fruite-categorie">
                                            {categories.map((cat) => (
                                                <li key={cat.id}>
                                                    <div className="d-flex justify-content-between fruite-name">
                                                        <Link to="/shop" state={{ category: cat.name }}>
                                                            <i className="fas fa-apple-alt me-2"></i>
                                                            {cat.name}
                                                        </Link>

                                                        <span>({cat.count || 0})</span>
                                                    </div>
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                </div>

                                {/* Sản phẩm nổi bật */}
                                <div className="col-lg-12">
                                    <h4 className="mb-4">Sản phẩm nổi bật</h4>

                                    {featured && featured.slice(0, 4).map(item => (
                                        <div
                                            className="d-flex align-items-center justify-content-start mb-4"
                                            key={item.id}
                                        >
                                            <div className="rounded" style={{ width: '100px', height: '100px' }}>
                                                <img
                                                    src={item.imageUrl || '/img/fruite-item-5.jpg'}
                                                    className="img-fluid rounded"
                                                    alt={item.name}
                                                    style={{
                                                        width: '100%',
                                                        height: '100%',
                                                        objectFit: 'cover'
                                                    }}
                                                />
                                            </div>

                                            <div className="ms-4">
                                                <h6 className="mb-2">{item.name}</h6>

                                                <div className="d-flex mb-2" style={{ fontSize: '12px' }}>
                                                    {renderStars(item.rating || 5)}
                                                </div>

                                                <div className="d-flex mb-2 flex-column">
                                                    {(item.discountPrice || item.DiscountPrice) ? (
                                                        <>
                                                            <h5 className="fw-bold me-2 text-danger">
                                                                {formatCurrency(item.discountPrice || item.DiscountPrice)}
                                                            </h5>

                                                            <h5 className="text-muted text-decoration-line-through">
                                                                {formatCurrency(item.price)}
                                                            </h5>
                                                        </>
                                                    ) : (
                                                        <h5 className="fw-bold me-2">
                                                            {formatCurrency(item.price)}
                                                        </h5>
                                                    )}
                                                </div>

                                                <Link
                                                    to={`/shop-detail/${item.id}`}
                                                    className="btn border border-secondary rounded-pill px-3 py-1 text-primary"
                                                    style={{ fontSize: '12px' }}
                                                >
                                                    Xem chi tiết
                                                </Link>
                                            </div>
                                        </div>
                                    ))}

                                    <div className="d-flex justify-content-center my-4">
                                        <Link
                                            to="/shop"
                                            className="btn border border-secondary px-4 py-3 rounded-pill text-primary w-100"
                                        >
                                            Xem thêm
                                        </Link>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            {/* Single Product End */}

            {/* Footer Start */}
            <div className="container-fluid bg-dark text-white-50 footer pt-5 mt-5">
                <div className="container py-5">
                    <div
                        className="pb-4 mb-4"
                        style={{ borderBottom: '1px solid rgba(226, 175, 24, 0.5)' }}
                    >
                        <div className="row g-4">
                            <div className="col-lg-3">
                                <a href="#">
                                    <h1 className="text-primary mb-0">Fruitables</h1>
                                    <p className="text-secondary mb-0">Sản phẩm tươi sạch</p>
                                </a>
                            </div>

                            <div className="col-lg-6">
                                <div className="position-relative mx-auto">
                                    <input
                                        className="form-control border-0 w-100 py-3 px-4 rounded-pill"
                                        type="email"
                                        placeholder="Email của bạn"
                                    />

                                    <button
                                        type="submit"
                                        className="btn btn-primary border-0 border-secondary py-3 px-4 position-absolute rounded-pill text-white"
                                        style={{
                                            top: 0,
                                            right: 0
                                        }}
                                    >
                                        Đăng ký ngay
                                    </button>
                                </div>
                            </div>

                            <div className="col-lg-3">
                                <div className="d-flex justify-content-end pt-3">
                                    <a className="btn btn-outline-secondary me-2 btn-md-square rounded-circle" href="">
                                        <i className="fab fa-twitter"></i>
                                    </a>

                                    <a className="btn btn-outline-secondary me-2 btn-md-square rounded-circle" href="">
                                        <i className="fab fa-facebook-f"></i>
                                    </a>

                                    <a className="btn btn-outline-secondary me-2 btn-md-square rounded-circle" href="">
                                        <i className="fab fa-youtube"></i>
                                    </a>

                                    <a className="btn btn-outline-secondary btn-md-square rounded-circle" href="">
                                        <i className="fab fa-linkedin-in"></i>
                                    </a>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="row g-5">
                        <div className="col-lg-3 col-md-6">
                            <div className="footer-item">
                                <h4 className="text-light mb-3">Vì sao chọn chúng tôi?</h4>

                                <p className="mb-4">
                                    Chúng tôi cam kết mang đến thực phẩm an toàn, tươi ngon,
                                    không hóa chất độc hại và tốt cho sức khỏe người tiêu dùng.
                                </p>

                                <a href="" className="btn border-secondary py-2 px-4 rounded-pill text-primary">
                                    Xem thêm
                                </a>
                            </div>
                        </div>

                        <div className="col-lg-3 col-md-6">
                            <div className="d-flex flex-column text-start footer-item">
                                <h4 className="text-light mb-3">Thông tin cửa hàng</h4>

                                <a className="btn-link" href="">Về chúng tôi</a>
                                <a className="btn-link" href="">Liên hệ</a>
                                <a className="btn-link" href="">Chính sách bảo mật</a>
                                <a className="btn-link" href="">Điều khoản & Điều kiện</a>
                                <a className="btn-link" href="">Chính sách đổi trả</a>
                                <a className="btn-link" href="">Câu hỏi thường gặp & Hỗ trợ</a>
                            </div>
                        </div>

                        <div className="col-lg-3 col-md-6">
                            <div className="d-flex flex-column text-start footer-item">
                                <h4 className="text-light mb-3">Tài khoản</h4>

                                <a className="btn-link" href="">Tài khoản của tôi</a>
                                <a className="btn-link" href="">Chi tiết cửa hàng</a>
                                <a className="btn-link" href="">Giỏ hàng</a>
                                <a className="btn-link" href="">Danh sách yêu thích</a>
                                <a className="btn-link" href="">Lịch sử mua hàng</a>
                                <a className="btn-link" href="">Đơn hàng quốc tế</a>
                            </div>
                        </div>

                        <div className="col-lg-3 col-md-6">
                            <div className="footer-item">
                                <h4 className="text-light mb-3">Liên hệ</h4>

                                <p>Địa chỉ: 236 Hoàng Quốc Việt, Hà Nội</p>
                                <p>Email: Example@gmail.com</p>
                                <p>Số điện thoại: +0123 4567 8910</p>
                                <p>Chấp nhận thanh toán</p>

                                <img src="/img/payment.png" className="img-fluid" alt="Phương thức thanh toán" />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            {/* Footer End */}

            {/* Copyright Start */}
            <div className="container-fluid copyright bg-dark py-4">
                <div className="container">
                    <div className="row">
                        <div className="col-md-6 text-center text-md-start mb-3 mb-md-0">
                            <span className="text-light">
                                <a href="#">
                                    <i className="fas fa-copyright text-light me-2"></i>
                                    Hệ thống Fruitables
                                </a>
                                , Bản quyền thuộc về chúng tôi.
                            </span>
                        </div>

                        <div className="col-md-6 my-auto text-center text-md-end text-white">
                            Thiết kế bởi{' '}
                            <a className="border-bottom" href="https://htmlcodex.com">
                                HTML Codex
                            </a>
                        </div>
                    </div>
                </div>
            </div>
            {/* Copyright End */}

            <a href="#" className="btn btn-primary border-3 border-primary rounded-circle back-to-top">
                <i className="fa fa-arrow-up"></i>
            </a>
        </>
    );
};

export default ShopDetail;
